"use client";

import type { LucideIcon } from "lucide-react";
import { Button } from "@/components/ui/button";

interface EmptyStateProps {
  icon: LucideIcon;
  title: string;
  description: string;
  action?: { label: string; onClick?: () => void };
}

export function EmptyState({
  icon: Icon,
  title,
  description,
  action,
}: EmptyStateProps) {
  return (
    <div className="flex flex-col items-center justify-center py-12 gap-4 text-center">
      <div className="size-12 rounded-full bg-muted flex items-center justify-center">
        <Icon className="size-6 text-muted-foreground" />
      </div>
      <div className="space-y-1">
        <p className="text-base font-semibold">{title}</p>
        <p className="text-sm text-muted-foreground max-w-xs">{description}</p>
      </div>
      {action && (
        <Button size="sm" onClick={action.onClick}>
          {action.label}
        </Button>
      )}
    </div>
  );
}

"use client";

import {
  Users,
  Inbox,
  Activity,
  DollarSign,
  Clock,
  TrendingUp,
  TrendingDown,
  Minus,
  type LucideIcon,
} from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import type { KpiMetric, IconName, TrendDirection } from "@/lib/types";

const iconMap: Record<IconName, LucideIcon> = {
  users: Users,
  inbox: Inbox,
  activity: Activity,
  "dollar-sign": DollarSign,
  clock: Clock,
};

const trendIconMap: Record<TrendDirection, LucideIcon> = {
  up: TrendingUp,
  down: TrendingDown,
  flat: Minus,
};

interface KpiCardProps {
  metric: KpiMetric;
  index: number;
}

export function KpiCard({ metric, index }: KpiCardProps) {
  const Icon = iconMap[metric.iconName];
  const TrendIcon = trendIconMap[metric.trend];

  // k05 is "Avg SLA" — down trend is good (faster SLA = improvement)
  const isInverse = metric.id === "k05";
  const isPositive = isInverse
    ? metric.trend === "down"
    : metric.trend === "up";
  const isNegative = isInverse
    ? metric.trend === "up"
    : metric.trend === "down";

  const deltaColorClass = isPositive
    ? "text-emerald-600"
    : isNegative
      ? "text-rose-600"
      : "text-muted-foreground";

  return (
    <Card
      className="animate-fade-in-up shadow-card hover:-translate-y-0.5 hover:shadow-soft-md transition-all duration-150"
      style={{
        animationDelay: `${index * 80}ms`,
        animationFillMode: "both",
      }}
    >
      <CardContent className="p-5">
        <div className="flex items-center justify-between">
          <p className="text-sm font-medium text-muted-foreground">
            {metric.label}
          </p>
          <div className="size-8 rounded-md bg-primary/10 text-primary flex items-center justify-center">
            <Icon className="size-4" />
          </div>
        </div>
        <p className="text-2xl font-bold leading-none tabular-nums mt-3">
          {metric.value}
        </p>
        <div className={`flex items-center gap-1 mt-2 ${deltaColorClass}`}>
          <TrendIcon className="size-3.5" />
          <span className="text-xs font-medium">
            {metric.delta > 0 ? "+" : ""}
            {metric.delta}%
          </span>
          <span className="text-xs text-muted-foreground">vs last week</span>
        </div>
      </CardContent>
    </Card>
  );
}

import { Clock } from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { requests } from "@/lib/mock/requests";
import { clients } from "@/lib/mock/clients";
import { getSlaStatus } from "@/lib/types";
import { EmptyState } from "@/components/common/empty-state";

const ANCHOR = "2026-04-10T12:00:00Z";

function formatSlaTime(slaDueAt: string): string {
  const dueMs = new Date(slaDueAt).getTime();
  const nowMs = new Date(ANCHOR).getTime();
  const diffHours = Math.round((dueMs - nowMs) / (1000 * 60 * 60));
  if (diffHours < 0) {
    return `${Math.abs(diffHours)}h overdue`;
  }
  return `due in ${diffHours}h`;
}

const warningRequests = requests
  .filter((r) => {
    const status = getSlaStatus(r.slaDueAt);
    return status === "warning" || status === "breached";
  })
  .sort((a, b) => {
    const aStatus = getSlaStatus(a.slaDueAt);
    const bStatus = getSlaStatus(b.slaDueAt);
    if (aStatus === "breached" && bStatus !== "breached") return -1;
    if (bStatus === "breached" && aStatus !== "breached") return 1;
    return new Date(a.slaDueAt).getTime() - new Date(b.slaDueAt).getTime();
  })
  .slice(0, 4);

export function SlaWarnings() {
  return (
    <Card className="shadow-card">
      <CardHeader className="pb-3">
        <CardTitle className="text-base font-semibold">SLA warnings</CardTitle>
        <p className="text-sm text-muted-foreground">
          Requests approaching or past deadline
        </p>
      </CardHeader>
      <CardContent>
        {warningRequests.length === 0 ? (
          <EmptyState
            icon={Clock}
            title="All clear"
            description="No SLA breaches right now"
          />
        ) : (
          <ul className="space-y-3">
            {warningRequests.map((req) => {
              const status = getSlaStatus(req.slaDueAt);
              const client = clients.find((c) => c.id === req.clientId);
              const timeLabel = formatSlaTime(req.slaDueAt);

              return (
                <li key={req.id} className="flex items-center gap-3">
                  <span
                    className={`size-2 rounded-full shrink-0 ${
                      status === "breached"
                        ? "bg-rose-500"
                        : "bg-amber-400"
                    }`}
                  />
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium truncate">{req.title}</p>
                    <p className="text-xs text-muted-foreground">
                      {client?.company ?? "Unknown"} · {timeLabel}
                    </p>
                  </div>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="shrink-0 h-7 px-2 text-xs"
                  >
                    View
                  </Button>
                </li>
              );
            })}
          </ul>
        )}
      </CardContent>
    </Card>
  );
}

import {
  CheckCircle2,
  UserPlus,
  Sparkles,
  User,
  MessageSquare,
  Plus,
  type LucideIcon,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { activity } from "@/lib/mock/activity";
import type { ActivityType } from "@/lib/types";

const ANCHOR = "2026-04-10T12:00:00Z";

type ActivityIconConfig = {
  icon: LucideIcon;
  className: string;
};

const activityIconMap: Record<ActivityType, ActivityIconConfig> = {
  request_delivered: { icon: CheckCircle2, className: "text-emerald-600" },
  client_added: { icon: UserPlus, className: "text-blue-500" },
  brief_generated: { icon: Sparkles, className: "text-violet-500" },
  request_assigned: { icon: User, className: "text-muted-foreground" },
  comment_added: { icon: MessageSquare, className: "text-muted-foreground" },
  request_created: { icon: Plus, className: "text-muted-foreground" },
};

function getInitials(name: string): string {
  return name
    .split(" ")
    .map((part) => part[0] ?? "")
    .slice(0, 2)
    .join("")
    .toUpperCase();
}

function formatRelativeTime(timestamp: string): string {
  const eventMs = new Date(timestamp).getTime();
  const nowMs = new Date(ANCHOR).getTime();
  const diffMs = nowMs - eventMs;
  const diffMinutes = Math.round(diffMs / (1000 * 60));
  const diffHours = Math.round(diffMs / (1000 * 60 * 60));
  const diffDays = Math.round(diffMs / (1000 * 60 * 60 * 24));

  if (diffMinutes < 60) return `${diffMinutes}m ago`;
  if (diffHours < 24) return `${diffHours}h ago`;
  return `${diffDays}d ago`;
}

const recentEvents = activity.slice(0, 10);

export function ActivityFeed() {
  return (
    <Card className="shadow-card">
      <CardHeader className="pb-3">
        <CardTitle className="text-base font-semibold">
          Recent activity
        </CardTitle>
      </CardHeader>
      <CardContent>
        <ul className="space-y-4">
          {recentEvents.map((event) => {
            const iconConfig = activityIconMap[event.type];
            const TypeIcon = iconConfig.icon;

            return (
              <li key={event.id} className="flex items-start gap-3">
                {/* Avatar with initials */}
                <div className="size-8 rounded-full bg-primary/10 text-primary text-xs font-semibold flex items-center justify-center shrink-0">
                  {getInitials(event.actorName)}
                </div>

                {/* Content */}
                <div className="flex-1 min-w-0 space-y-0.5">
                  <p className="text-sm leading-snug">
                    <strong className="font-medium">{event.actorName}</strong>{" "}
                    {event.action}{" "}
                    <strong className="font-medium">{event.target}</strong>
                  </p>
                  <p className="text-xs text-muted-foreground">
                    {formatRelativeTime(event.timestamp)}
                  </p>
                </div>

                {/* Type icon */}
                <TypeIcon className={`size-4 shrink-0 mt-0.5 ${iconConfig.className}`} />
              </li>
            );
          })}
        </ul>
      </CardContent>
    </Card>
  );
}

import { PageHeader } from "@/components/common/page-header";
import { KpiCard } from "@/components/dashboard/kpi-card";
import { QuickActions } from "@/components/dashboard/quick-actions";
import { SlaWarnings } from "@/components/dashboard/sla-warnings";
import { ActivityFeed } from "@/components/dashboard/activity-feed";
import { kpiMetrics } from "@/lib/mock/metrics";

export default function DashboardPage() {
  return (
    <>
      <PageHeader title="Dashboard" subtitle="Welcome back, Priya" />

      {/* KPI grid: 5 cols on lg, 2 on md, 1 on mobile */}
      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-5 mb-6">
        {kpiMetrics.map((m, i) => (
          <KpiCard key={m.id} metric={m} index={i} />
        ))}
      </div>

      {/* 3-col grid: QuickActions (2/3) + SlaWarnings (1/3) */}
      <div className="grid gap-4 lg:grid-cols-3 mb-6">
        <div className="lg:col-span-2">
          <QuickActions />
        </div>
        <SlaWarnings />
      </div>

      <ActivityFeed />
    </>
  );
}
